"""v11.a A-to-Z report generator (docs/evidence/v11_protocol.md R4). Reads ONLY committed result files; every number printed comes from a file. A result whose file does not exist is printed as `not run`.
No API key is used or needed. usage (repository root): python docs/evidence/v11_report.py [out.md]   (default kaggle/judged_v11a/REPORT_V11A.md)"""
import csv, glob, json, math, os, sys

OUT = sys.argv[1] if len(sys.argv) > 1 else 'kaggle/judged_v11a/REPORT_V11A.md'; os.makedirs(os.path.dirname(OUT), exist_ok=True)
J = lambda p: json.load(open(p)) if os.path.exists(p) else None; exists = os.path.exists
f3 = lambda x: '--' if x in (None, '') else f'{float(x):.3f}'; pc = lambda x: '--' if x is None else f'{100 * x:.1f}%'
L = ['# DiagRAG v11.a: A-to-Z report (generated; no number is typed by hand)', '',
     'Generated by `docs/evidence/v11_report.py` from the committed result files. `not run` means the file does not exist. Protocol: `docs/evidence/v11_protocol.md`. **No API key was used for anything in this report.** The free-tier LLM arm on new corpora is v11.b and is not part of it.', '']

# ---------------- 1. main runs (ESCI, 32 faults)
L += ['## 1. Main pipeline on ESCI (frozen v6 code), every judged run', '', '| Run | Stack | Seed | Detectors / repairs / both | L1 | L2 | U1 (bar 0.50) | N1 natural gain | Verdict |', '|---|---|---|---|---|---|---|---|---|']
MAIN = [('v6 GPU', 'kaggle/judged_gpu_v6_seed50', 'GPU', 50), ('v6 CPU', 'kaggle/judged_cpu_run_v6_seed50', 'CPU', 50), ('v7 CPU (regression)', 'kaggle/judged_cpu_run_v7_seed50', 'CPU', 50),
        ('v8 GPU', 'kaggle/judged_gpu_v8_seed52', 'GPU', 52), ('v11.a GPU', 'kaggle/judged_gpu_v11a_seed55', 'GPU', 55)]
gpu = {}
for name, d, stack, seed in MAIN:
    V = J(os.path.join(d, 'VERDICT.json'))
    if not V: L.append(f'| {name} | {stack} | {seed} | not run | | | | | |'); continue
    gl = V.get('loop_gates') or {}; g = V.get('guarantee') or {}; n1 = V.get('N1') or {}
    L.append(f"| {name} | {stack} | {seed} | {V['detectors_pass']} / {V['repairs_pass']} / {V['solved_both']} | {100 * g.get('heldout_clean_loss', float('nan')):.2f}% ({gl.get('L1', '-')}) | {f3(g.get('mean_closure'))} ({gl.get('L2', '-')}) | "
             f"{f3(V.get('unseen_mean_closure'))} ({gl.get('U1', '-')}) | {100 * n1.get('delta', float('nan')):+.2f} ({gl.get('N1', '-')}) | **{V['verdict']}** |")
    if stack == 'GPU' and name.startswith(('v6 GPU', 'v8', 'v11')): gpu[seed] = V['verdict']
k = sum(v == 'ADOPTED' for v in gpu.values()); L += ['', f"**Adoption across the GPU seeds run so far ({', '.join(str(s) for s in sorted(gpu))}): adopted in {k} of {len(gpu)}.** " + ('The v11.a GPU seed (55) is `not run`.' if 55 not in gpu else '')]
L += ['The count is read together with `docs/evidence/v10_adoption_intervals.md`, which classes each detector by its interval against the 0.70 bar.', '']
AI = J('docs/evidence/v10_adoption_intervals.json')
if AI:
    L += ['| Run | Stored verdict | Determinate passes | Uncertain | Count range | Decided by the data? |', '|---|---|---|---|---|---|']
    for r in AI: L.append(f"| {r['run']} | {r['verdict']} | {r['counts']['DET_PASS']} | {r['counts']['UNCERTAIN']} | {r['lower']} to {r['upper']} | {r['decided']} |")
    L.append('')

# ---------------- 2. audits
L += ['## 2. Data-hygiene audits on the saved episodes (descriptive)', '', '| Run | Exact fault (faulted) | AUROC | A1 leak effect (pts) | A3 permutation mean [min, max] (band 0.45 to 0.55) | A5 AUROC bootstrap mean | A6 query-text-only AUROC |', '|---|---|---|---|---|---|---|']
for name, p in (('v6 GPU seed 50', 'docs/evidence/v8_audit_v6gpu.json'), ('v8 GPU seed 52', 'docs/evidence/v8_audit_v8gpu.json'), ('v11.a GPU seed 55', 'docs/evidence/v11a_audit_seed55.json')):
    A = J(p)
    if not A: L.append(f'| {name} | not run | | | | | |'); continue
    a3 = A['A3_label_permutation']; L.append(f"| {name} | {pc(A['reference']['exact_fault_accuracy_on_faulted'])} | {f3(A['reference']['auroc_fault_vs_clean'])} | {A['A1_split_leakage']['drop_points']:.2f} | {a3['auroc_mean']:.3f} [{a3['auroc_min']:.3f}, {a3['auroc_max']:.3f}] "
                                                         f"({'in band' if a3['pass_in_band'] else 'OUT OF BAND'}) | {f3(A['A5_bootstrap_stability']['auroc']['mean'])} | {f3(A['A6_query_text_only']['auroc_fault_vs_clean'])} |")
L += ['', 'The label-permutation control missed its band in the audits that have run; `docs/evidence/V10_DIAGNOSIS.md` and amendment E3 of `v8_protocol.md` give the (post-hoc) covariate-shift explanation. It is not proof of absence of leakage.', '']

# ---------------- 3. ports
L += ['## 3. Port arm: the same 20 faults, gates and stack on other BEIR corpora', '', '| Corpus | Folder | Clean Hit@5 (test) | Detectors | Repairs | Solved (of 20) | Ports (>= 15) | Unsolved |', '|---|---|---|---|---|---|---|---|']
PORTS = [('SciFact', 'kaggle/judged_port2_scifact'), ('FiQA', 'kaggle/judged_port2_fiqa'), ('NFCorpus', 'kaggle/judged_port3_nfcorpus'), ('ArguAna', 'kaggle/judged_port3_arguana'), ('SCIDOCS (v11.a)', 'kaggle/judged_port4_scidocs')]
for name, d in PORTS:
    V = J(os.path.join(d, 'PORT_VERDICT.json'))
    L.append(f"| {name} | {os.path.basename(d)} | not run | | | | | |" if not V else f"| {name} | {os.path.basename(d)} | {V['clean_hit5']['test']:.3f} | {V['detectors_pass']} | {V['repairs_pass']} | {V['solved_both']} | {V['suite_ports']} | {', '.join(V['not_solved']) or '-'} |")
L += ['', 'A fault with fewer than 20 held-out positives (THIN or untrained) counts as not solved. No corpus is dropped; no combined sentence is made without listing every corpus. Most trained detectors sit at the AUROC ceiling on every corpus, so this arm says little about subtle faults.', '']
for name, d in PORTS[2:]:
    S = os.path.join(d, 'port_episodes_summary.csv')
    if exists(S):
        thin = [r['fault'] for r in csv.DictReader(open(S)) if int(r['hard_test']) < 20]
        if thin: L.append(f"- {name}: faults with fewer than 20 hard held-out episodes (reported THIN or untrained): {', '.join(thin)}")
L.append('')

# ---------------- 4. supervised text baseline
L += ['## 4. Supervised text baseline against the telemetry attributor (fault vs clean, held-out)', '', '| Corpus | Attributor AUROC | Word TF-IDF + LR AUROC | Attributor minus text, 95% interval | Verdict | Attributor exact | Text exact |', '|---|---|---|---|---|---|---|']
for name, p in (('NFCorpus', 'docs/evidence/v10_textbaseline_nfcorpus.json'), ('ArguAna', 'docs/evidence/v10_textbaseline_arguana.json'), ('SCIDOCS (v11.a)', 'docs/evidence/v11a_textbaseline_scidocs.json')):
    T = J(p)
    if not T: L.append(f'| {name} | not run | | | | | |'); continue
    a = T['arms']; t = a['T1_word']; d = t['attributor_minus_text']
    L.append(f"| {name} | {f3(a['attributor']['auroc'])} | {f3(t['auroc'])} | {d['mean']:+.3f} [{d['ci_lo']:+.3f}, {d['ci_hi']:+.3f}] | {d['verdict']} | {pc(a['attributor']['exact_fault_accuracy_on_faulted'])} | {pc(t['exact_fault_accuracy_on_faulted'])} |")
L += ['', 'Simple supervised text models with about 25 training positives per fault. A fine-tuned cross-encoder or an LLM given labelled examples is not tested.', '']

# ---------------- 5. composed / multi-label / diagnosis
L += ['## 5. Composed faults, multi-label naming, and the C2 / Q03 diagnosis', '']
E = J('docs/evidence/v9_emergent_breakdown_v7.json'); M = J('docs/evidence/v10_multilabel_result.json'); D = J('docs/evidence/v10_diagnosis_v6_v8.json')
if E: a = E['all']; L.append(f"- v7 composed arm (155 held-out episodes, one seed, CPU): every cause named {a['both_named_new']['k']}/155 ({pc(a['both_named_new']['rate'])}); sequential closure {a['sequential_closure']['k']}/155; oracle-forward closure {a['oracle_forward_closure']['k']}/155. Emergent failures (no component fails alone): {E['by_alone_category']['NONE_FAIL_ALONE']['n']} episodes, named {pc(E['by_alone_category']['NONE_FAIL_ALONE']['both_named_new']['rate'])}.")
if M:
    h = M['heldout']['multilabel']; c = M['heldout_clean_false_labels']; L.append(f"- Multi-label naming rule (tau {M['tau']}): every cause named {h['both_named']['k']}/155 ({pc(h['both_named']['rate'])}), precision {f3(h['precision'])}, {h['mean_labels_per_episode']:.2f} labels per episode; **cost: {pc(c['multilabel_nonempty'])} of clean held-out episodes get a label, against {pc(c['single_label_argmax_not_none'])} for the single-label rule.** Naming only; no repair or closure result.")
if D: L.append(f"- C2 detector v6 to v8 change: z = {D['C2_v6_vs_v8']['z']:.2f}, p about {D['C2_v6_vs_v8']['two_sided_p_normal_approx']:.2f} (within sampling noise at 50 positives). Q03 is called clean in {pc(D['v6_gpu_seed50']['Q03_called_clean'])} (v6) and {pc(D['v8_gpu_seed52']['Q03_called_clean'])} (v8) of its held-out episodes: telemetry does not see it.")
L.append('')

# ---------------- 6. LLM baselines already complete (free tier, ESCI)
L += ['## 6. Free-tier LLM baselines on ESCI (already complete, from the earlier runs)', '']
LB = J('kaggle/judged_llm_baselines/LLM_BASELINES_RESULT.json')
if LB:
    L += ['| Arm | B1 n | LLM AUROC | Telemetry AUROC | Verdict |', '|---|---|---|---|---|']
    for p, v in LB.items(): b = v.get('B1', {}); L.append(f"| {v['model']} | {b.get('n')} | {f3(b.get('auroc_llm'))} | {f3(b.get('auroc_ours'))} | {b.get('verdict')} |")
    L += ['', 'These are zero-shot free-tier judges against a supervised attributor, on ESCI only. No frontier model was run. **The same comparison on other corpora is v11.b and is `not run`.**']
else: L.append('not run')
L.append('')

# ---------------- 7. not run
L += ['## 7. Not run, and why', '',
      '- **v11.b (free-tier LLM diagnosis on the port corpora):** pre-registered in `docs/evidence/v11b_protocol.md`; waits for the owner.',
      '- **Frontier-LLM arm:** no funded key (the gateway balance is 0).',
      '- **Document-text baseline on ESCI, fine-tuned text model, composed-arm repeat, full-suite port (Q02, Q09, C2, ShopNova faults), density-matched permutation control, benchmark release:** no code written and tested, or needs the owner.',
      '- **U1 and Q03:** not redesigned. Changing either after seeing results would be tuning to the test.', '',
      '## 8. What this report is not', '',
      'It is not a score. The score is the owner\'s judgement. Faults are injected by the authors on one e-commerce corpus (main) and four or five BEIR corpora (ports); the code was written by an AI assistant under the owner\'s direction; the natural-traffic sample is the same 1,648 queries in every main run.']
open(OUT, 'w').write('\n'.join(L) + '\n'); print('wrote', OUT, len(L), 'lines')
